class C1ExpertCourseData {
 static List<String> _rotate(List<String> v,int a)=>List<String>.generate(v.length,(i)=>v[(i-a+v.length)%v.length]);
 static B1Question _q(String p,List<String> o,int a,String e)=>B1Question(p,_rotate(o,a),a,e);
 static B1Lesson _build(_Spec s){final n=s.number;final w=[s.meaning,'التعبير عن المكان','التعبير عن الزمن الماضي','طلب الإذن'];final tr=[s.translation,'لم يبدأ الاجتماع بعد.','سأعود إلى المنزل غداً.','لا تتضمن الجملة هذا المعنى.'];final fm=[s.form,'geçmiş zaman','istek kipi','yer tamlayıcısı'];final fn=[s.functionText,'تحديد المكان فقط','تغيير زمن الجملة فقط','تكوين سؤال عن السعر'];return B1Lesson(unitId:s.unitId,globalNumber:n,title:s.title,goal:s.goal,rule:s.rule,examples:[s.sentence+' | '+s.translation,s.example],dialogue:s.dialogue,speakingTask:s.task,questions:[_q('ما معنى «${s.term}»؟',w,n%4,'«${s.term}» تعني: ${s.meaning}.'),_q('ما ترجمة الجملة التركية؟',tr,(n+1)%4,s.translation),_q('أي تعبير يرتبط بمهارة الدرس؟',fm,(n+2)%4,'التعبير المستهدف «${s.form}». '+s.rule),_q('ما الوظيفة التواصلية الأساسية؟',fn,(n+3)%4,s.functionText),_q('أي ممارسة تثبت إتقان المهارة؟',[s.task,'حفظ كلمات دون سياق','نسخ نص دون فهم','تجاهل القرائن والأدلة'],(n+1)%4,s.task)]);}
 static final List<B1Lesson> lessons=[
_Spec(unitId:'c1-u7',number:361,title:'صياغة أسئلة البحث الدقيقة',goal:'تحويل موضوع واسع إلى سؤال بحث محدد قابل للتحقق.',rule:'ينبغي أن يحدد سؤال البحث المتغيرات والنطاق والفئة والسياق دون افتراض النتيجة مسبقاً.',term:'araştırma sorusu',meaning:'سؤال بحث',sentence:'Bu araştırma, uzaktan çalışmanın ekip verimliliğini nasıl etkilediğini inceliyor.',translation:'يدرس هذا البحث كيف يؤثر العمل عن بعد في إنتاجية الفريق.',form:'araştırma sorusunu sınırlandırmak',functionText:'تحديد نطاق السؤال البحثي بدقة.',task:'اكتب ثلاثة أسئلة بحث ثم اختر الأكثر قابلية للإجابة بالأدلة.',example:'Araştırma sorusunu açık ve ölçülebilir biçimde yazdım.|صغت سؤال البحث بوضوح وقابلية للقياس.',dialogue:'A: Konu çok geniş değil mi؟ — أليس الموضوع واسعاً جداً؟\nB: Soruyu belirli bir dönem ve örneklemle sınırlandırdım. — حددت السؤال بفترة وعينة.'),
_Spec(unitId:'c1-u7',number:362,title:'تقييم موثوقية المصادر',goal:'فحص المؤلف والمنهج والتاريخ والجهة الناشرة وتعارض المصالح.',rule:'لا يكفي شكل المصدر؛ افحص أصل البيانات والمنهج والشفافية وإمكانية التحقق المستقل.',term:'güvenilir kaynak',meaning:'مصدر موثوق',sentence:'Kaynağın yöntemini ve veri toplama sürecini ayrıca değerlendirdik.',translation:'قيّمنا منهج المصدر وعملية جمع البيانات بشكل منفصل.',form:'kaynak güvenilirliği',functionText:'تقدير موثوقية المصدر قبل الاستشهاد به.',task:'قارن مصدرين حول قضية واحدة وحدد مؤشرات الموثوقية في كل منهما.',example:'Kaynağın güvenilirliğini bağımsız verilerle kontrol ettim.|تحققت من موثوقية المصدر ببيانات مستقلة.',dialogue:'A: Bu makaleye güvenebilir miyiz؟ — هل يمكن الوثوق بهذه المقالة؟\nB: Önce yöntemini ve yazarın uzmanlığını inceleyelim. — لنفحص منهجها وخبرة الكاتب أولاً.'),
_Spec(unitId:'c1-u7',number:363,title:'تحديد حدود الدراسة',goal:'شرح ما لا تستطيع النتائج إثباته بسبب العينة أو المنهج أو الزمن.',rule:'اذكر حدود العينة والقياس والتعميم، ولا تعرض القيد كأنه يبطل الدراسة كلها.',term:'araştırmanın sınırlılıkları',meaning:'حدود البحث',sentence:'Örneklem küçük olduğu için sonuçlar tüm nüfusa genellenemez.',translation:'لا يمكن تعميم النتائج على السكان كافة لأن العينة صغيرة.',form:'sınırlılıkları belirtmek',functionText:'بيان حدود الاستنتاجات بإنصاف.',task:'اكتب فقرة حدود لدراسة افتراضية مع اقتراح بحث لاحق.',example:'Çalışmanın sınırlılıklarını açıkça belirttim.|حددت حدود الدراسة بوضوح.',dialogue:'A: Sonuçlar herkesi kapsıyor mu؟ — هل تشمل النتائج الجميع؟\nB: Hayır, örneklemin kapsamı sınırlı. — لا، نطاق العينة محدود.'),
_Spec(unitId:'c1-u7',number:364,title:'التمييز بين الارتباط والسببية',goal:'منع تحويل تزامن متغيرين إلى ادعاء سببي دون تصميم مناسب.',rule:'الارتباط يصف تغيراً مشتركاً؛ السببية تحتاج أدلة وتصميماً يستبعد التفسيرات البديلة.',term:'nedensellik',meaning:'علاقة سببية',sentence:'İki değişken arasındaki ilişki tek başına nedenselliği kanıtlamaz.',translation:'العلاقة بين متغيرين لا تثبت السببية وحدها.',form:'korelasyon ve nedensellik',functionText:'التمييز بين الارتباط والسببية.',task:'حلل ادعاءً إحصائياً واكتب تفسيرين بديلين للارتباط.',example:'Korelasyonu nedensellik olarak yorumlamadım.|لم أفسر الارتباط على أنه سببية.',dialogue:'A: Birlikte değişmeleri neden olduklarını gösterir mi؟ — هل تغيرهما معاً يثبت أن أحدهما سبب الآخر؟\nB: Hayır, başka etkenler de olabilir. — لا، قد توجد عوامل أخرى.'),
_Spec(unitId:'c1-u7',number:365,title:'تركيب نتائج الدراسات السابقة',goal:'دمج مصادر متعددة في خريطة موضوعية بدلاً من تلخيص كل مصدر منفرداً.',rule:'نظم الأدبيات حسب الاتجاهات والاختلافات والمنهج، ثم أبرز الفجوة التي يعالجها بحثك.',term:'literatür sentezi',meaning:'تركيب الأدبيات البحثية',sentence:'Önceki çalışmaların ortak bulgularını ve ayrıştıkları noktaları bir araya getirdim.',translation:'جمعت النتائج المشتركة للدراسات السابقة ونقاط اختلافها.',form:'çalışmaları sentezlemek',functionText:'دمج نتائج عدة مصادر في تحليل واحد.',task:'اكتب فقرة تقارن أربع دراسات وتستخلص اتجاهاً وفجوة بحثية.',example:'Literatürü temalara göre sentezledim.|ركبت الأدبيات وفق محاور موضوعية.',dialogue:'A: Her çalışmayı ayrı mı özetledin؟ — هل لخصت كل دراسة على حدة؟\nB: Hayır, ortak temalara göre birleştirdim. — لا، جمعتها وفق الموضوعات المشتركة.'),
_Spec(unitId:'c1-u7',number:366,title:'بناء الاعتراض والرد العلمي',goal:'عرض اعتراض قوي والرد عليه بالأدلة دون تشويه موقف الطرف الآخر.',rule:'قدّم الاعتراض بأمانة، ثم حدد نطاق صحته، وبعد ذلك رد بالدليل أو التقييد أو البديل.',term:'karşı sav',meaning:'حجة مضادة',sentence:'Bu görüş önemli bir noktaya değinse de verilerin tamamını açıklamıyor.',translation:'رغم أن هذا الرأي يثير نقطة مهمة فإنه لا يفسر البيانات كلها.',form:'karşı savı yanıtlamak',functionText:'الرد على الحجة المضادة بحجة منضبطة.',task:'اكتب اعتراضاً قوياً على أطروحتك ثم أجب عنه بدليلين.',example:'Karşı görüşü adil biçimde ele alıp yanıtladım.|عرضت الرأي المقابل بإنصاف ثم رددت عليه.',dialogue:'A: Karşı görüşü neden ekledin؟ — لماذا أضفت الرأي المقابل؟\nB: Tartışmanın dengeli ve ikna edici olması için. — ليكون النقاش متوازناً ومقنعاً.'),
_Spec(unitId:'c1-u7',number:367,title:'التحفظ في صياغة الادعاءات',goal:'استخدام درجات اليقين المناسبة لما تسمح به الأدلة.',rule:'اختر قدراً لغوياً من اليقين يتناسب مع حجم العينة وقوة التصميم وتكرار النتائج.',term:'ihtiyatlı ifade',meaning:'صياغة متحفظة',sentence:'Bu bulgular, belirli koşullarda bir artış olabileceğini düşündürmektedir.',translation:'تشير هذه النتائج إلى احتمال حدوث زيادة في ظروف محددة.',form:'kesinlik derecesi',functionText:'مواءمة درجة اليقين مع قوة الدليل.',task:'أعد كتابة خمس جمل قطعية بصياغة علمية متحفظة.',example:'İddiamı kanıtların gücüne göre sınırlandırdım.|قيدت ادعائي وفق قوة الأدلة.',dialogue:'A: Kesin bir sonuç çıkarabilir miyiz؟ — هل يمكننا استنتاج نتيجة مؤكدة؟\nB: Mevcut veriler daha temkinli bir ifade gerektiriyor. — البيانات الحالية تتطلب صياغة أكثر حذراً.'),
_Spec(unitId:'c1-u7',number:368,title:'ترتيب الأدلة بحسب قوتها',goal:'تقييم نوع الدليل وجودته واتساقه وصلته بالسؤال.',rule:'رتب الأدلة وفق المنهج والعينة والتكرار والاستقلال، لا وفق موافقتها لرأيك.',term:'kanıt hiyerarşisi',meaning:'تدرج قوة الأدلة',sentence:'Tek bir örnek, sistematik araştırmalar kadar güçlü kanıt oluşturmaz.',translation:'لا يشكل مثال واحد دليلاً بقوة الدراسات المنهجية.',form:'kanıtın gücünü değerlendirmek',functionText:'تقدير قوة الدليل وصلته بالادعاء.',task:'رتب ستة أنواع من الأدلة وفسر معايير ترتيبك.',example:'Kanıtları yöntem ve tutarlılık açısından değerlendirdim.|قيّمت الأدلة من حيث المنهج والاتساق.',dialogue:'A: Bu örnek yeterli mi؟ — هل هذا المثال كافٍ؟\nB: Tek başına değil; daha kapsamlı veriler gerekli. — ليس وحده، نحتاج بيانات أوسع.'),
_Spec(unitId:'c1-u7',number:369,title:'عرض نتائج البحث',goal:'تقديم النتائج بترتيب منطقي مع رسوم وشرح لا يبالغ في الاستنتاج.',rule:'ابدأ بسؤال البحث والمنهج ثم النتائج الرئيسية وحدودها ودلالاتها العملية.',term:'bulguları sunmak',meaning:'يعرض النتائج',sentence:'Bulgular, başlangıçtaki varsayımı yalnızca kısmen destekliyor.',translation:'تدعم النتائج الفرضية الأولية جزئياً فقط.',form:'araştırma sunumu',functionText:'عرض النتائج مع حدود الاستدلال.',task:'قدم عرضاً من خمس دقائق يتضمن سؤال البحث والمنهج وثلاث نتائج.',example:'Bulguları açık grafikler ve kısa açıklamalarla sundum.|عرضت النتائج برسوم واضحة وشروح موجزة.',dialogue:'A: Sonuçlar varsayımı doğruladı mı؟ — هل أكدت النتائج الفرضية؟\nB: Kısmen; bazı değişkenler farklı sonuç verdi. — جزئياً؛ بعض المتغيرات أعطت نتائج مختلفة.'),
_Spec(unitId:'c1-u7',number:370,title:'مراجعة منهجية البحث والحجاج',goal:'دمج سؤال البحث وتقييم المصدر والحدود والاعتراضات في مراجعة واحدة.',rule:'تحقق من اتساق السؤال والمنهج والدليل والاستنتاج، وأعد صياغة أي قفزة منطقية.',term:'araştırma tutarlılığı',meaning:'اتساق البحث',sentence:'Araştırma sorusu ile kullanılan yöntem arasında tutarlılık bulunmalıdır.',translation:'ينبغي أن يوجد اتساق بين سؤال البحث والمنهج المستخدم.',form:'yöntem ve sonuç uyumu',functionText:'التحقق من اتساق المنهج والنتيجة.',task:'راجع مشروعاً بحثياً وحدد ثلاث نقاط قوة وثلاثة تحسينات.',example:'Araştırmanın mantıksal bütünlüğünü gözden geçirdim.|راجعت الاتساق المنطقي للبحث.',dialogue:'A: En önemli kontrol noktası nedir؟ — ما أهم نقطة للتحقق؟\nB: Yöntemin soruya gerçekten yanıt verip vermediği. — هل يجيب المنهج فعلاً عن السؤال.'),
_Spec(unitId:'c1-u8',number:371,title:'المعنى التداولي والنية الضمنية',goal:'فهم ما يقصده المتحدث وراء المعنى الحرفي وفق المقام.',rule:'حلل العلاقة بين العبارة والنية والسياق والمعرفة المشتركة، ولا تفترض قصداً بلا قرائن.',term:'örtük niyet',meaning:'نية ضمنية',sentence:'Pencereyi biraz açabilir misiniz؟',translation:'هل يمكنكم فتح النافذة قليلاً؟ (طلب مهذب لا سؤال عن القدرة فقط).',form:'edimsel anlam',functionText:'استنتاج الفعل الكلامي المقصود من العبارة.',task:'حلل خمس عبارات وحدد هل هي طلب أم اقتراح أم نقد غير مباشر.',example:'Sözcenin gerçek işlevini bağlamdan anladım.|فهمت الوظيفة الحقيقية للقول من السياق.',dialogue:'A: Sadece izin mi soruyor؟ — هل يسأل عن الإذن فقط؟\nB: Aslında nazikçe pencerenin açılmasını istiyor. — إنه في الحقيقة يطلب فتح النافذة بأدب.'),
_Spec(unitId:'c1-u8',number:372,title:'تلطيف الاختلاف في الحوار',goal:'التعبير عن الاعتراض دون تصعيد أو التقليل من الطرف الآخر.',rule:'استخدم الاعتراف بجزء صحيح ثم قدم تحفظك وسببه واقتراحاً بديلاً.',term:'nazikçe itiraz etmek',meaning:'يعترض بأدب',sentence:'Bu noktaya katılıyorum; ancak başka bir açıdan değerlendirmek isterim.',translation:'أتفق مع هذه النقطة، لكنني أود تقييمها من زاوية أخرى.',form:'yumuşatılmış itiraz',functionText:'صياغة اعتراض مهذب ومتوازن.',task:'حوّل خمسة اعتراضات مباشرة إلى صيغ دبلوماسية.',example:'Görüş ayrılığını saygılı bir dille ifade ettim.|عبرت عن الاختلاف بلغة محترمة.',dialogue:'A: Bu öneriye katılmıyorum. — لا أوافق على المقترح.\nB: Kısmen haklısınız, ancak bir noktayı eklemek isterim. — لديكم حق جزئياً، لكن أود إضافة نقطة.'),
_Spec(unitId:'c1-u8',number:373,title:'اختيار السجل في المواقف الحساسة',goal:'تكييف درجة الرسمية والوضوح في مواقف تتطلب لباقة.',rule:'وازن بين احترام المخاطب ووضوح الرسالة وتجنب الغموض الذي يعرقل الفهم.',term:'hitap biçimi',meaning:'صيغة المخاطبة',sentence:'Bu konuyu sizinle ayrıca değerlendirmek isterim.',translation:'أود مناقشة هذا الموضوع معكم على نحو منفصل.',form:'uygun hitap',functionText:'اختيار صيغة مخاطبة ملائمة.',task:'اكتب رسالة اعتذار رسمية ثم نسخة ودية مع الحفاظ على المعنى.',example:'Muhataba uygun bir hitap biçimi seçtim.|اخترت صيغة مخاطبة مناسبة للمستلم.',dialogue:'A: Bu ifade fazla mı doğrudan؟ — هل هذه العبارة مباشرة أكثر من اللازم؟\nB: Daha yumuşak bir biçim tercih edebiliriz. — يمكننا اختيار صيغة ألطف.'),
_Spec(unitId:'c1-u8',number:374,title:'فهم الإحالات الثقافية',goal:'تفسير الإشارات إلى العادات والأحداث والأمثال في السياق.',rule:'حدد المرجع الثقافي ووظيفته ولا تفترض أن الترجمة الحرفية تنقل دلالته.',term:'kültürel gönderme',meaning:'إحالة ثقافية',sentence:'Bu deyim, Türk kültüründeki misafirperverlik anlayışına gönderme yapıyor.',translation:'يشير هذا التعبير إلى مفهوم الضيافة في الثقافة التركية.',form:'kültürel bağlam',functionText:'فهم الإشارة الثقافية في سياقها.',task:'اختر ثلاثة أمثال تركية واشرح مرجعها الثقافي واستعمالها.',example:'Kültürel göndermeyi açıklayarak anlamı korudum.|حافظت على المعنى بشرح الإحالة الثقافية.',dialogue:'A: Bu söz neden kullanıldı؟ — لماذا استُخدم هذا القول؟\nB: Ortak bir kültürel değeri hatırlatıyor. — إنه يذكّر بقيمة ثقافية مشتركة.'),
_Spec(unitId:'c1-u8',number:375,title:'إعادة الصياغة للوساطة اللغوية',goal:'نقل معنى طرف إلى آخر بلغة محايدة تحفظ المقصود.',rule:'احذف الأحكام الشخصية، ووضح النقاط المتفق عليها، وانسب كل موقف إلى صاحبه.',term:'arabuluculuk',meaning:'وساطة',sentence:'Tarafların beklentilerini tarafsız bir dille yeniden ifade ettim.',translation:'أعدت التعبير عن توقعات الأطراف بلغة محايدة.',form:'tarafsız yeniden ifade',functionText:'نقل الرسالة دون تحريف أو انحياز.',task:'قم بدور وسيط وأعد صياغة موقفين متعارضين بصورة محايدة.',example:'Her iki tarafın görüşünü dengeli biçimde aktardım.|نقلت رأي الطرفين بصورة متوازنة.',dialogue:'A: Benim söylediğimi doğru aktardınız mı؟ — هل نقلت كلامي بدقة؟\nB: Evet, anlamı koruyup ifadeyi tarafsızlaştırdım. — نعم، حافظت على المعنى وجعلت الصياغة محايدة.'),
_Spec(unitId:'c1-u8',number:376,title:'معالجة الغموض وسوء الفهم',goal:'طلب التوضيح وإصلاح التواصل عندما تحتمل العبارة أكثر من معنى.',rule:'حدد موضع الالتباس، واطلب مثالاً أو إعادة صياغة، ثم أكد الفهم قبل المتابعة.',term:'yanlış anlaşılma',meaning:'سوء فهم',sentence:'Yanlış anlamayı önlemek için kastınızı biraz açabilir misiniz؟',translation:'لتجنب سوء الفهم، هل يمكنكم توضيح ما تقصدونه؟',form:'açıklama istemek',functionText:'إصلاح التواصل بطلب توضيح.',task:'اكتب حواراً يعالج سوء فهم عبر ثلاثة أسئلة توضيحية.',example:'Belirsizliği açıklığa kavuşturduk.|أزلنا الغموض ووضحناه.',dialogue:'A: Tam olarak neyi kastediyorsunuz؟ — ما الذي تقصده تحديداً؟\nB: Şunu demek istiyorum: ... — أقصد ما يلي: ...'),
_Spec(unitId:'c1-u8',number:377,title:'الفروق التداولية في التعبيرات الاصطلاحية',goal:'تمييز ملاءمة التعبير الاصطلاحي بحسب العلاقة والمقام.',rule:'قد يكون التعبير طبيعياً بين الأصدقاء وغير مناسب في مراسلة رسمية؛ قيّم النبرة والجمهور.',term:'deyimin kullanım alanı',meaning:'مجال استخدام التعبير الاصطلاحي',sentence:'Bu deyim günlük konuşmada doğal, resmî raporda ise uygun değildir.',translation:'هذا التعبير طبيعي في الحديث اليومي لكنه غير مناسب في تقرير رسمي.',form:'bağlama uygun deyim',functionText:'اختيار التعبير وفق المقام.',task:'صنف عشرة تعبيرات إلى يومية ومهنية ومحايدة.',example:'Deyimin kullanım alanını dikkate aldım.|راعيت مجال استخدام التعبير.',dialogue:'A: Bu deyimi raporda kullanabilir miyim؟ — هل أستخدم هذا التعبير في التقرير؟\nB: Daha nötr bir ifade seçmek daha uygun. — اختيار تعبير محايد أنسب.'),
_Spec(unitId:'c1-u8',number:378,title:'فهم الفكاهة والسخرية',goal:'تفسير الفكاهة والسخرية من التناقض والسياق دون الاعتماد على اللفظ وحده.',rule:'لاحظ التباين بين المتوقع والمذكور، ونبرة المتحدث والعلاقة بين الأطراف.',term:'ironi',meaning:'سخرية أو مفارقة',sentence:'Harika, yine tam zamanında gelen bir gecikme!',translation:'رائع، تأخير جاء في موعده تماماً! (سخرية من التأخير).',form:'ironik anlatım',functionText:'التعبير عن معنى معاكس ظاهرياً بقصد ساخر.',task:'حلل ثلاثة أمثلة وحدد القرائن التي تكشف السخرية.',example:'İroniyi sözcüklerden çok bağlamdan çıkardım.|استنتجت السخرية من السياق أكثر من الكلمات.',dialogue:'A: Konuşmacı gerçekten memnun mu؟ — هل المتحدث سعيد حقاً؟\nB: Hayır, gecikmeyi ironik biçimde eleştiriyor. — لا، ينتقد التأخير بسخرية.'),
_Spec(unitId:'c1-u8',number:379,title:'التفاوض عبر الثقافات',goal:'التفاوض مع مراعاة اختلاف أساليب المباشرة والوقت واتخاذ القرار.',rule:'اسأل عن توقعات الطرف الآخر ولا تعمم الصفات الثقافية، واتفق على معايير واضحة.',term:'kültürlerarası müzakere',meaning:'تفاوض بين الثقافات',sentence:'Karar sürecindeki beklentileri baştan netleştirdik.',translation:'وضحنا التوقعات المتعلقة بعملية اتخاذ القرار منذ البداية.',form:'beklenti yönetimi',functionText:'إدارة التوقعات في التفاوض متعدد الثقافات.',task:'صمم حوار تفاوض بين فريقين يختلفان في أسلوب اتخاذ القرار.',example:'Kültürel farklılıkları genellemeden ele aldım.|تعاملت مع الاختلافات الثقافية دون تعميم.',dialogue:'A: Kararı hemen verebilir miyiz؟ — هل يمكننا اتخاذ القرار فوراً؟\nB: Önce tüm tarafların beklentilerini netleştirelim. — لنوضح توقعات جميع الأطراف أولاً.'),
_Spec(unitId:'c1-u8',number:380,title:'مراجعة الكفاءة التداولية والوساطة',goal:'دمج فهم النية والسجل والإحالة الثقافية وإصلاح سوء الفهم.',rule:'اختر الصياغة التي تحفظ المعنى وتناسب العلاقة والجمهور والسياق.',term:'iletişimsel uygunluk',meaning:'الملاءمة التواصلية',sentence:'İletinin içeriği kadar kime ve nasıl söylendiği de önemlidir.',translation:'لا تقل أهمية لمن وكيف يقال الكلام عن محتواه.',form:'pragmatik yeterlilik',functionText:'اختيار التعبير المناسب للسياق الاجتماعي.',task:'أنجز محاكاة وساطة بين طرفين ثم قيّم ملاءمة لغتك.',example:'İletişimsel tercihlerimi bağlama göre gözden geçirdim.|راجعت اختياراتي التواصلية وفق السياق.',dialogue:'A: Doğru kelimeyi seçmek yeterli mi؟ — هل يكفي اختيار الكلمة الصحيحة؟\nB: Hayır, bağlam ve ilişki de önemlidir. — لا، فالسياق والعلاقة مهمان أيضاً.'),
_Spec(unitId:'c1-u9',number:381,title:'كتابة مقال حجاجي متكامل',goal:'بناء أطروحة ومقدمات وأدلة واعتراض وخاتمة مترابطة.',rule:'اجعل كل فقرة تؤدي وظيفة واضحة، واربط الادعاءات بالأدلة والانتقالات المنطقية.',term:'savunmacı makale',meaning:'مقال حجاجي',sentence:'Makale, karşı görüşleri değerlendirerek temel savını gerekçelendiriyor.',translation:'يبرر المقال أطروحته الأساسية عبر تقييم الآراء المقابلة.',form:'argüman yapısı',functionText:'بناء حجة مكتوبة متماسكة.',task:'اكتب مقالاً من 600 كلمة يتضمن اعتراضاً ورداً وخاتمة.',example:'Argümanımı tutarlı paragraflarla geliştirdim.|طورت حجتي بفقرات متماسكة.',dialogue:'A: Her paragraf aynı fikri mi destekliyor؟ — هل تدعم كل فقرة الفكرة نفسها؟\nB: Evet, fakat farklı kanıt ve işlevlerle. — نعم، لكن بأدلة ووظائف مختلفة.'),
_Spec(unitId:'c1-u9',number:382,title:'دمج المصادر في نص مستقل',goal:'تركيب الأفكار من مصادر متعددة بصياغة أصلية وتوثيق واضح.',rule:'قارن المصادر، وانسب الأفكار، وتجنب تجميع الاقتباسات دون تحليل رابط.',term:'kaynakları bütünleştirmek',meaning:'دمج المصادر',sentence:'Üç kaynağın bulgularını ortak bir çerçevede değerlendirdim.',translation:'قيّمت نتائج ثلاثة مصادر ضمن إطار مشترك.',form:'kaynak sentezi',functionText:'دمج الأدلة والأفكار في نص أصيل.',task:'اكتب فقرة تجمع ثلاثة مصادر وتوضح العلاقة بينها.',example:'Kaynakları kendi analizimle bütünleştirdim.|دمجت المصادر بتحليلي الخاص.',dialogue:'A: Kaynakları art arda mı sıraladın؟ — هل سردت المصادر واحداً تلو الآخر؟\nB: Hayır, aralarındaki ilişkiyi açıkladım. — لا، شرحت العلاقة بينها.'),
_Spec(unitId:'c1-u9',number:383,title:'كتابة الملخص التنفيذي',goal:'اختصار تقرير طويل لصانع قرار مع الحفاظ على النتائج والتوصية.',rule:'ضع القرار المطلوب والنتائج الرئيسية والتوصية والمخاطر في ترتيب يسهل مسحه سريعاً.',term:'yönetici özeti',meaning:'ملخص تنفيذي',sentence:'Yönetici özeti, temel bulguları ve önerilen eylemi kısa biçimde sunuyor.',translation:'يعرض الملخص التنفيذي النتائج الأساسية والإجراء المقترح بإيجاز.',form:'özlü raporlama',functionText:'تقديم خلاصة عملية موجزة.',task:'اكتب ملخصاً تنفيذياً من 180 كلمة لتقرير طويل.',example:'Raporun ana sonuçlarını kısa bir özette topladım.|جمعت نتائج التقرير في ملخص موجز.',dialogue:'A: Ayrıntılı yöntemi de ekleyelim mi؟ — هل نضيف المنهج التفصيلي؟\nB: Yalnızca karar için gerekli kısmı. — فقط الجزء الضروري لاتخاذ القرار.'),
_Spec(unitId:'c1-u9',number:384,title:'العرض الشفهي الارتجالي المنظم',goal:'تقديم إجابة مرتبة دون إعداد نص كامل مسبقاً.',rule:'استخدم مقدمة قصيرة ونقطتين داعمتين ومثالاً وخاتمة، واطلب لحظة للتفكير عند الحاجة.',term:'doğaçlama konuşma',meaning:'حديث ارتجالي',sentence:'Soruyu üç başlık altında yanıtlayarak düşüncelerimi düzenledim.',translation:'نظمت أفكاري بالإجابة عن السؤال تحت ثلاثة عناوين.',form:'konuşmayı yapılandırmak',functionText:'تنظيم الحديث الارتجالي بوضوح.',task:'أجب عن سؤال غير متوقع خلال دقيقتين وفق بنية واضحة.',example:'Hazırlıksız konuşurken ana fikrimi korudum.|حافظت على فكرتي الرئيسة أثناء الحديث دون إعداد.',dialogue:'A: Biraz düşünmek için zaman alabilir miyim؟ — هل يمكنني أخذ وقت قصير للتفكير؟\nB: Elbette, ardından görüşünüzü paylaşın. — بالتأكيد، ثم شارك رأيك.'),
_Spec(unitId:'c1-u9',number:385,title:'إدارة الأسئلة الصعبة',goal:'الإجابة عن سؤال معقد مع تحديد الافتراضات والحدود.',rule:'أعد صياغة السؤال، ووضح ما يمكن الإجابة عنه، واذكر حدود المعرفة دون مراوغة.',term:'zor soruyu yanıtlamak',meaning:'الإجابة عن سؤال صعب',sentence:'Bu sorunun iki boyutu var; önce verilerle desteklenen kısmı açıklayayım.',translation:'لهذا السؤال جانبان؛ دعوني أوضح أولاً الجزء المدعوم بالبيانات.',form:'soruya yapılandırılmış yanıt',functionText:'إجابة منظمة ودقيقة عن سؤال معقد.',task:'تدرب على خمسة أسئلة نقدية وقدم إجابات تتضمن حدوداً واضحة.',example:'Soruyu netleştirip kanıta dayalı yanıt verdim.|وضحت السؤال وقدمت إجابة قائمة على الدليل.',dialogue:'A: Bu sonucu her durumda genelleyebilir misiniz؟ — هل تعمم النتيجة في كل الحالات؟\nB: Hayır, yalnızca incelenen koşullar için geçerli. — لا، تنطبق فقط على الظروف المدروسة.'),
_Spec(unitId:'c1-u9',number:386,title:'المشاركة في مناظرة أكاديمية',goal:'عرض موقف والدفاع عنه والاستجابة للحجج المقابلة.',rule:'استمع إلى الحجة كاملة، ولخصها بإنصاف، ثم رد على أقوى نقطة لا على أضعف صياغة.',term:'akademik münazara',meaning:'مناظرة أكاديمية',sentence:'Karşı tarafın temel savını özetleyip kanıtlarına yanıt verdim.',translation:'لخصت الحجة الأساسية للطرف المقابل ورددت على أدلته.',form:'kanıta dayalı tartışma',functionText:'إدارة مناظرة تقوم على الأدلة.',task:'شارك في مناظرة وسجل الحجة الأقوى للطرف الآخر وردك عليها.',example:'Tartışmada kişilere değil iddialara odaklandım.|ركزت في النقاش على الادعاءات لا الأشخاص.',dialogue:'A: Karşı tarafın görüşünü doğru aktardın mı؟ — هل نقلت رأي الطرف الآخر بدقة؟\nB: Önce özetledim, sonra itirazımı sundum. — لخصته أولاً ثم قدمت اعتراضي.'),
_Spec(unitId:'c1-u9',number:387,title:'مراجعة الأقران للنصوص المتقدمة',goal:'تقديم ملاحظات محددة قابلة للتنفيذ على نص زميل.',rule:'قيّم وضوح الأطروحة والبنية والأدلة والترابط والأسلوب، وقدم مثالاً لكل ملاحظة.',term:'akran değerlendirmesi',meaning:'تقييم الأقران',sentence:'Metnin güçlü yönlerini ve geliştirilmesi gereken bölümlerini belirttim.',translation:'حددت نقاط قوة النص والأقسام التي تحتاج إلى تطوير.',form:'yapılandırılmış geri bildirim',functionText:'تقديم تغذية راجعة محددة ومحترمة.',task:'راجع مقالاً وفق خمسة معايير وقدم ثلاث توصيات قابلة للتنفيذ.',example:'Akran değerlendirmesinde somut örnekler kullandım.|استخدمت أمثلة ملموسة في تقييم الأقران.',dialogue:'A: Sadece hataları mı işaretledin؟ — هل أشرت إلى الأخطاء فقط؟\nB: Hayır, güçlü yönleri ve çözüm önerilerini de yazdım. — لا، كتبت نقاط القوة والحلول أيضاً.'),
_Spec(unitId:'c1-u9',number:388,title:'تحرير الأسلوب والاتساق النهائي',goal:'مراجعة النص من حيث الوضوح والإحالة والتكرار والنبرة.',rule:'حرر على مراحل: بنية النص ثم الفقرة والجملة ثم المفردات وعلامات الترقيم.',term:'son redaksiyon',meaning:'مراجعة تحريرية نهائية',sentence:'Son redaksiyonda terim birliğini ve paragraf geçişlerini kontrol ettim.',translation:'تحققت في المراجعة النهائية من توحيد المصطلحات والانتقالات بين الفقرات.',form:'metin tutarlılığı',functionText:'ضبط الاتساق الأسلوبي والمصطلحي.',task:'حرر تقريراً طويلاً وسجل التغييرات الجوهرية وأسبابها.',example:'Metnin son biçiminde tutarlılığı sağladım.|حققت الاتساق في النسخة النهائية.',dialogue:'A: Önce hangi bölümü düzelttin؟ — أي جزء صححت أولاً؟\nB: Önce yapıyı, sonra dili. — البنية أولاً ثم اللغة.'),
_Spec(unitId:'c1-u9',number:389,title:'محاكاة تقييم C1 المتكامل',goal:'أداء مهام قراءة واستماع وكتابة وتحدث في سيناريو واحد.',rule:'وزع الوقت، وحدد المطلوب في كل مهمة، وراجع الإجابات وفق الدقة والترابط والملاءمة.',term:'bütünleşik değerlendirme',meaning:'تقييم متكامل',sentence:'Dört beceriyi aynı konu çevresinde kullanarak değerlendirmeyi tamamladım.',translation:'أكملت التقييم باستخدام المهارات الأربع حول موضوع واحد.',form:'beceri bütünleştirme',functionText:'دمج المهارات الأربع في تقييم واحد.',task:'أنجز محاكاة تشمل نصاً ومحاضرة ومقالاً وعرضاً شفهياً.',example:'Performansımı ölçütlere göre değerlendirdim.|قيّمت أدائي وفق معايير محددة.',dialogue:'A: Hangi beceri daha çok zaman aldı؟ — أي مهارة استغرقت وقتاً أطول؟\nB: Yazma, çünkü kanıtları düzenlemem gerekti. — الكتابة لأنني احتجت إلى تنظيم الأدلة.'),
_Spec(unitId:'c1-u9',number:390,title:'ملف الإنجاز النهائي لمستوى C1',goal:'جمع أدلة الأداء وتقييم التطور وتحديد أهداف لاحقة.',rule:'اختر عينات متنوعة، واكتب سبب اختيارها وما تعلمته وكيف تطور أداؤك.',term:'C1 portfolyosu',meaning:'ملف إنجاز C1',sentence:'Portfolyom, farklı türlerdeki çalışmalarımı ve gelişim sürecimi gösteriyor.',translation:'يعرض ملف إنجازي أعمالي بأنواع مختلفة ومسار تطوري.',form:'öz değerlendirme',functionText:'توثيق الأداء والتطور بأدلة.',task:'أنشئ ملفاً يضم أفضل أعمالك وتقييماً ذاتياً وخطة تطوير لاحقة.',example:'C1 portfolyomu kanıtlarla tamamladım.|أكملت ملف C1 بالأدلة.',dialogue:'A: Portfolyoda yalnızca en iyi çalışman mı var؟ — هل يحتوي الملف على أفضل عمل فقط؟\nB: Hayır, gelişimimi gösteren örnekler de var. — لا، فيه أيضاً نماذج تظهر تطوري.'),
 ].map(_build).toList(growable:false);
}
